<?php if($preview): ?><p>Total sebelumnya <strong><?= payment_history_money($record['total']) ?></strong> · Setelah disimpan <strong><?= $cancel?'Dibatalkan':payment_history_money($preview['after']['total']) ?></strong></p><dl class="ph-components"><?php foreach($preview['after']['items'] as $item): ?><div><dt><?= $e($item['label']) ?></dt><dd><?= payment_history_money($item['amount']) ?></dd></div><?php endforeach; ?></dl><dl class="ph-components"><?php foreach(['Tanggal'=>[$record['source_date'],$preview['after']['source_date']],'Periode'=>[$record['source_period'],$preview['after']['source_period']],'Metode'=>[$record['method'],$preview['after']['method']],'Catatan'=>[$record['note'],$preview['after']['note']]] as $label=>[$old,$new]): ?><div><dt><?= $label ?></dt><dd><?= $e($old?:'Tidak tercatat') ?> → <?= $e($new?:'Tidak tercatat') ?></dd></div><?php endforeach; ?></dl><p><?= nl2br($e($preview['reason'])) ?></p><form method="post"><input type="hidden" name="csrf_token" value="<?= $e($_SESSION['csrf_payment']) ?>"><input type="hidden" name="stage" value="save"><input type="hidden" name="preview_key" value="<?= $key ?>"><button class="btn btn-primary"><?= transaction_authorization_requires_request()?'Kirim Pengajuan':'Simpan Perubahan' ?></button></form><details><summary>Kembali Mengubah</summary><?php endif; ?>
<form method="post"><input type="hidden" name="csrf_token" value="<?= $e($_SESSION['csrf_payment']) ?>"><input type="hidden" name="version" value="<?= (int)$record['version'] ?>"><input type="hidden" name="cancelled" value="<?= $cancel?'1':'0' ?>">
<label class="field-row">Tanggal bayar<input class="field-input" type="datetime-local" step="1" name="date" value="<?= $e($values['date']??'') ?>"></label><label class="field-row">Periode<input class="field-input" name="period" maxlength="100" value="<?= $e($values['period']??'') ?>"></label><label class="field-row">Metode pembayaran<input class="field-input" name="method" maxlength="100" value="<?= $e($values['method']??'') ?>"></label>
<?php foreach($record['items'] as $n=>$item): ?><label class="field-row"><?= $e($item['label']) ?> (Rp)<input class="field-input" inputmode="decimal" name="amount[<?= $n ?>]" value="<?= $e($values['amount'][$n]??$item['amount']) ?>" required></label><?php endforeach; ?>
<label class="field-row">Catatan<textarea class="field-input" name="note" maxlength="1000"><?= $e($values['note']??'') ?></textarea></label><label class="field-row">Alasan perubahan<textarea class="field-input" name="reason" minlength="10" maxlength="500" required><?= $e($values['reason']??'') ?></textarea></label><button class="btn <?= $cancel?'btn-danger':'btn-primary' ?>">Periksa Perubahan</button></form><?php if($preview): ?></details><?php endif; ?><a class="btn btn-ghost" href="<?= $e($returnUrl) ?>">Kembali ke Riwayat</a></section></div></main></div><script src="../assets/js/app.js"></script></body></html>
